module fifo #(
    parameter DEPTH = 8,
    parameter PTR_W = 3
) (
    input  wire             clk,
    input  wire             reset,
    input  wire             wr_en,
    input  wire             rd_en,
    output reg  [PTR_W-1:0] wr_ptr,
    output reg  [PTR_W-1:0] rd_ptr,
    output reg              wrap_bit,
    output wire             full,
    output wire             empty
);

    reg [PTR_W-1:0] mem [0:DEPTH-1];

    wire fifo_full = (wr_ptr == rd_ptr) && wrap_bit;

    always @(posedge clk) begin
        if (reset) begin
            wr_ptr   <= {PTR_W{1'b0}};
            rd_ptr   <= {PTR_W{1'b0}};
            wrap_bit <= 1'b0;
        end else begin
            if (wr_en && !fifo_full) begin
                mem[wr_ptr] <= mem[wr_ptr];
                if (wr_ptr == DEPTH - 1) begin
                    wr_ptr   <= {PTR_W{1'b0}};
                    wrap_bit <= ~wrap_bit;
                end else begin
                    wr_ptr <= wr_ptr + 1'b1;
                end
            end
            if (rd_en && !empty) begin
                if (rd_ptr == DEPTH - 1)
                    rd_ptr <= {PTR_W{1'b0}};
                else
                    rd_ptr <= rd_ptr + 1'b1;
            end
        end
    end

    // Bug: full ignores wrap_bit, so a wrapped-full FIFO reads as not full.
    assign full  = (wr_ptr == rd_ptr) && !wrap_bit;
    assign empty = (wr_ptr == rd_ptr) && !wrap_bit;

endmodule

testbench:
`timescale 1ns/1ps

module tb;

    localparam DEPTH = 8;

    reg clk;
    reg reset;
    reg wr_en;
    reg rd_en;
    wire [2:0] wr_ptr;
    wire [2:0] rd_ptr;
    wire wrap_bit;
    wire full;
    wire empty;

    integer cycle;

    fifo #(.DEPTH(DEPTH)) dut (
        .clk(clk),
        .reset(reset),
        .wr_en(wr_en),
        .rd_en(rd_en),
        .wr_ptr(wr_ptr),
        .rd_ptr(rd_ptr),
        .wrap_bit(wrap_bit),
        .full(full),
        .empty(empty)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    initial begin
        cycle = 0;
        reset = 1'b1;
        wr_en = 1'b0;
        rd_en = 1'b0;
        repeat (2) @(posedge clk);
        reset = 1'b0;
    end

    always @(posedge clk) begin
        cycle = cycle + 1;
        if (!reset) begin
            if (cycle >= 3 && cycle <= 10)
                wr_en = 1'b1;
            else
                wr_en = 1'b0;

            if (cycle == 12) begin
                if (full !== 1'b1) begin
                    $display(
                        "[FAIL] cycle=%0d signal=full expected=1 actual=0 message=\"full flag ignores wrap-around state\"",
                        cycle
                    );
                    $finish;
                end else begin
                    $display("[PASS] all checks passed");
                    $finish;
                end
            end
        end
    end

    initial begin
        #500;
        $display(
            "[FAIL] cycle=%0d signal=full expected=1 actual=0 message=\"simulation timeout before full check\"",
            cycle
        );
        $finish;
    end

endmodule

